python3 << 'EOF'
import json, re

log_path = '/home/ubuntu/.agent-ml-research-idea_gen_0509_9/projects/event-gated-adaptive-horizon/logs/chats/cron_hook_exp_008d_civo_trigger_s3.jsonl'
with open(log_path) as f:
    lines = f.readlines()

print(f"Total lines: {len(lines)}")

# Search each line for metrics
for i, line in enumerate(lines):
    try:
        d = json.loads(line)
        text = d.get('text', '')
        if 'value_mean' in text or 'eval_return' in text:
            # Extract values
            vms = re.findall(r'value_mean.{1,5}?([\d.]+)', text)
            evals = re.findall(r'eval_return.{1,5}?([\d.]+)', text)
            steps = re.findall(r'\[(\d+)\]', text)
            if vms or evals:
                print(f"Line {i}: steps={steps[:3]}, vm={vms[:5]}, eval={evals[:5]}")
    except:
        pass

# Also check for 'metrics' or 'summary' format
for i, line in enumerate(lines):
    try:
        d = json.loads(line)
        text = d.get('text', '')
        if 'step' in text and ('83' in text or '268' in text or '452' in text):
            print(f"\nLine {i} (has key numbers): {text[:300]}")
    except:
        pass
EOF

